"""S3-006 slices A, B and D integration cases; executed by the guarded hosted database suite."""
from test_database import check, role, assert_sql, deny, uid, W, A, P, C, U
from test_management import rpc


def export(section, page=0):
    return f"public.seq_export('{section}',{page})"


def delete_sql(req, confirmation='DELETE MY WORKSPACE'):
    return f"public.seq_delete_workspace(jsonb_build_object('requestId','{req}','confirmation','{confirmation}'))"


def deny_any(sql, states):
    handlers = ' '.join(f"WHEN SQLSTATE '{s}' THEN RETURN;" for s in states)
    return f"DO $$ BEGIN BEGIN {sql}; EXCEPTION {handlers} END; RAISE EXCEPTION 'Expected one of {' '.join(states)}'; END $$;"


def integration():
    imp = {'requestId': uid(90), 'keys': ['sample-ada'], 'listName': 'Gate sample'}
    new_draft = {'requestId': uid(92), 'campaignId': None, 'revision': None, 'name': 'Gate draft', 'recipients': [P], 'content': {'note': '', 'firstMessage': 'Hi {{name}}', 'followups': []}}
    edit_draft = {**new_draft, 'campaignId': C, 'revision': 1}
    runtime = role('sequence_auth_runtime')
    # A: export
    check('export manifest and sections cover only the own tenant', role() + assert_sql(f"({export('manifest')}->'counts'->>'prospects')::int=1 AND ({export('manifest')}->>'workspaceId')='{W}' AND ({export('manifest')}->>'formatVersion')='sequence-export-1' AND ({export('manifest')}->>'sendingEnabled')::boolean=false") + assert_sql(f"jsonb_array_length({export('prospects')})=1 AND {export('prospects')}->0->>'id'='{P}' AND {export('enrollments')}->0->>'status'='Held' AND {export('actions',3)}='[]'::jsonb AND jsonb_array_length({export('approvalRecipients')})=1"))
    check('export invalid section, anonymous and revoked access denied', role() + deny(f"SELECT {export('auth_sessions')}", '22023') + deny(f"SELECT {export('prospects',-1)}", '22023') + 'RESET ROLE;' + role('anon', '') + deny(f"SELECT {export('manifest')}", '42501') + 'RESET ROLE;' + f"UPDATE sequence_private.access_allowlist SET active=false WHERE user_id='{U}';" + role() + deny(f"SELECT {export('manifest')}", '42501'))
    # D: meters and growth gate
    check('usage recorded by runtime role only and summed into today', runtime + "SELECT sequence_private.usage_record(100); SELECT sequence_private.usage_record(50); RESET ROLE;" + assert_sql("(SELECT requests=2 AND response_bytes=150 FROM sequence_private.usage_counters WHERE day=current_date)") + runtime + deny("SELECT sequence_private.usage_record(-1)", '22023') + 'RESET ROLE;' + role() + deny("SELECT sequence_private.usage_record(1)", '42501'), "DELETE FROM sequence_private.usage_counters WHERE day=current_date;")
    check('status reports three meters and allows growth with a fresh reading', role() + assert_sql(f"({rpc('status',{})}->>'growthAllowed')::boolean AND jsonb_array_length({rpc('status',{})}->'meters')=3 AND ({rpc('status',{})}->>'sendingEnabled')::boolean=false AND ({rpc('status',{})}->>'totalProspects')::int=1") + deny(f"SELECT {rpc('status',{'page':0})}", '22023'))
    check('unverified egress blocks growth but not edits, stop or export', role() + deny(f"SELECT {rpc('import',imp)}", '53400') + deny(f"SELECT {rpc('save-draft',new_draft)}", '53400') + assert_sql(f"NOT ({rpc('status',{})}->>'growthAllowed')::boolean AND {rpc('status',{})}->'reasons' ? 'egress-unverified'") + f"SELECT {rpc('save-draft',edit_draft)};" + f"SELECT {rpc('control',{'requestId':uid(97),'campaignId':C,'revision':2,'action':'stop'})};" + assert_sql(f"({export('manifest')}->>'workspaceId')='{W}'"), "UPDATE sequence_private.provider_readings SET read_at=now()-interval '8 days' WHERE note='fixture';")
    check('provider reading at seventy percent denies growth and warns below it', role() + deny(f"SELECT {rpc('import',imp)}", '53400') + assert_sql(f"{rpc('status',{})}->'reasons' ? 'database-70-percent' AND ({rpc('status',{})}->'meters'->0->>'state')='deny'") + 'RESET ROLE;' + "UPDATE sequence_private.provider_readings SET value=340000000 WHERE meter='database_bytes';" + role() + assert_sql(f"({rpc('status',{})}->>'growthAllowed')::boolean AND ({rpc('status',{})}->'meters'->0->>'state')='warn'") + f"SELECT {rpc('import',imp)};", "INSERT INTO sequence_private.provider_readings(meter,value,note) VALUES('database_bytes',400000000,'fixture');")
    check('maintenance keeps usage counters for ninety days only', runtime + "SELECT sequence_private.auth_maintenance(); RESET ROLE;" + assert_sql("(SELECT count(*) FROM sequence_private.usage_counters WHERE day<current_date-90)=0 AND EXISTS(SELECT 1 FROM sequence_private.usage_counters WHERE day=current_date-10)"), "INSERT INTO sequence_private.usage_counters(day,requests,response_bytes) VALUES(current_date-91,1,1),(current_date-10,1,1) ON CONFLICT DO NOTHING;")
    # B: deletion
    req = uid(98)
    check('delete requires exact confirmation and keeps data otherwise', role() + deny(f"SELECT {delete_sql(req,'delete')}", '22023') + deny(f"SELECT public.seq_delete_workspace(jsonb_build_object('requestId','{req}','confirmation','DELETE MY WORKSPACE','workspaceId','{uid(2,2)}'))", '22023') + 'RESET ROLE;' + assert_sql(f"EXISTS(SELECT 1 FROM public.seq_workspaces WHERE id='{W}') AND (SELECT active FROM sequence_private.access_allowlist WHERE user_id='{U}')"))
    check('delete requires a provider sign-in younger than five minutes', role() + deny(f"SELECT {delete_sql(req)}", '28000') + 'RESET ROLE;' + assert_sql(f"EXISTS(SELECT 1 FROM public.seq_workspaces WHERE id='{W}')"), f"UPDATE auth.sessions SET created_at=now()-interval '6 minutes' WHERE id='{uid(50)}';")
    check('delete removes tenant rows, fences sessions, records a tombstone and repeats idempotently', role() + f"""
DO $$ DECLARE r1 jsonb; r2 jsonb; BEGIN
 r1={delete_sql(req)}; r2={delete_sql(req)};
 IF r1<>r2 OR NOT (r1->>'deleted')::boolean OR (r1->'removed'->>'prospects')::int<>1 OR (r1->'removed'->>'actions')::int<>1 THEN RAISE EXCEPTION 'Deletion result mismatch'; END IF;
END $$; RESET ROLE;""" + assert_sql(f"NOT EXISTS(SELECT 1 FROM public.seq_workspaces WHERE id='{W}') AND NOT EXISTS(SELECT 1 FROM public.seq_prospects WHERE workspace_id='{W}') AND NOT EXISTS(SELECT 1 FROM public.seq_accounts WHERE workspace_id='{W}') AND NOT EXISTS(SELECT 1 FROM sequence_private.enrollments WHERE workspace_id='{W}') AND NOT EXISTS(SELECT 1 FROM sequence_private.logical_actions WHERE workspace_id='{W}') AND NOT EXISTS(SELECT 1 FROM sequence_private.approval_recipients WHERE workspace_id='{W}')") + assert_sql(f"(SELECT NOT active FROM sequence_private.access_allowlist WHERE user_id='{U}') AND (SELECT revoked_at IS NOT NULL AND sealed_tokens='{{}}' FROM sequence_private.auth_sessions WHERE user_id='{U}')") + assert_sql(f"EXISTS(SELECT 1 FROM sequence_private.deletion_tombstones WHERE workspace_id='{W}' AND user_id='{U}' AND request_id='{req}' AND identity_removed_at IS NULL)") + assert_sql(f"(SELECT count(*) FROM public.seq_prospects WHERE workspace_id='{uid(2,2)}')=1 AND (SELECT active FROM sequence_private.access_allowlist WHERE user_id='{uid(1,2)}')"))
    check('deleted workspace cannot be revived by management, late results or leases', role() + deny(f"SELECT {rpc('snapshot',{'page':0})}", '42501') + deny(f"SELECT {export('manifest')}", '42501') + 'RESET ROLE;' + role('sequence_worker') + deny_any(f"INSERT INTO sequence_private.enrollments(workspace_id,account_id,campaign_id,content_revision_id,approval_id,prospect_id,baseline_observation_id,status) VALUES('{W}','{A}','{C}','{uid(7)}','{uid(8)}','{P}','{uid(9)}','Held')", ['23503', '42501']) + deny_any(f"SELECT sequence_private.acquire_storage_lease('{W}','{A}','{uid(20)}')", ['42501', 'P0002', '23503']) + 'RESET ROLE;' + deny(f"INSERT INTO public.seq_prospects(workspace_id,account_id,recipient_key,display_name,source,observed_at) VALUES('{W}','{A}','late','Late result','synthetic',now())", '23503'), role() + f"SELECT {delete_sql(req)}; RESET ROLE;")
    check('operator identity removal needs a recorded deletion and removes the Auth user', deny(f"SELECT sequence_private.operator_remove_identity('{U}','{uid(60)}')", 'P0002') + role() + f"SELECT {delete_sql(req)}; RESET ROLE;" + f"SELECT sequence_private.operator_remove_identity('{U}','{uid(60)}');" + assert_sql(f"NOT EXISTS(SELECT 1 FROM auth.users WHERE id='{U}') AND NOT EXISTS(SELECT 1 FROM sequence_private.access_allowlist WHERE user_id='{U}') AND (SELECT identity_removed_at IS NOT NULL FROM sequence_private.deletion_tombstones WHERE workspace_id='{W}') AND EXISTS(SELECT 1 FROM auth.users WHERE id='{uid(1,2)}')"))
    check('runtime and client roles cannot remove identities or read tombstones', runtime + deny(f"SELECT sequence_private.operator_remove_identity('{U}','{uid(60)}')", '42501') + deny('SELECT * FROM sequence_private.deletion_tombstones', '42501') + 'RESET ROLE;' + role() + deny(f"SELECT sequence_private.operator_remove_identity('{U}','{uid(60)}')", '42501') + deny('SELECT * FROM sequence_private.provider_readings', '42501'))
